        "section": "  \u003Cb\u003EIn questions 57 to 58, identify the word that has the stress on the first syllable.\u003C/b\u003E",
        "image": "",
        "answer": "b",
        "solution": "stress is the degree of force applied when pronouncung the syllable(s) of a word. the stress syllable is the syllable on which the speaker uses more muscular energy and breath effort when pronouncing a word. we have various degrees of stress patterns such as, primary stress, secondary stress, tertiary stress and weakly stressed.\n\nbisyllabic (two syllable) words are usually stressed on the first syllable except the first syllable is a prefix.  example (DOCtor) is stressed on the first syllable but ''disprove'' is stressed on the second syllable because the first is a prefix, so it becomes (disPROVE). in the above question, all the options but ''saloon'' have a prefix. that means saloon has its stress on the first syllable.\n\nNote however that, there are certain exceptions to the above rule when the word is either a ''çompound noun'' or a ''compound verb''",
        "examtype": "utme",
        "examyear": "2001",
        "questionNub": 57,
        "hasPassage": 0,
        "category": "others"
      },
