          "c": "intact",
          "d": "confuse"
        },
        "section": "\u003Cb\u003EIn each of questions 74 and 75, identify the word that has the\nstress on the first syllable.\u003C/b\u003E",
        "image": "",
        "answer": "b",
        "solution": "dismiss\n\ncomment is both a compound noun and verb. as a noun, the stress would be on the first syllable and for a verb, the stress would be on the second syllable. since it wasnt specified in the question as a verb, that means it is a noun. it would be stressed thus: COMment\n\nwords with prefix always have their stress on the second syllable. Dismiss, intact and confuse all have prefixes and would be stressed on the second sylle as:\n\ndisMISS\n\ninTACT\n\nconFUSE",
        "examtype": "utme",
